"""Render research_paper/evidence_registry.md from research_paper/.rcs (run from the repo root)."""
import json
from pathlib import Path
R = Path("research_paper/.rcs")
ev = json.load(open(R / "evidence/research_evidence.json", encoding="utf-8"))["items"]
cm = json.load(open(R / "claims/claim_evidence_map.json", encoding="utf-8"))
src = json.load(open(R / "corpus/source_registry.json", encoding="utf-8"))["sources"]
E = {e["id"]: e for e in ev}
out = ["# Evidence registry and claim-to-evidence map", "",
       "Generated by `research_paper/tools/render_registry.py` from the RCE artifacts in `research_paper/.rcs/`",
       "(built by `tools/build_rcs.py`, `tools/build_registry.py`). Do not edit by hand; edit the builders and re-run.",
       "Every numeric value listed under an evidence item was checked to occur in its locator file before the",
       "artifacts were written. Gate reports: `research_paper/.rcs/audits/gates/`.", "",
       f"## 1. Evidence items ({len(ev)})", "", "| ID | Kind | Strength | Locator | Summary | Values checked in file |", "|---|---|---|---|---|---|"]
for e in ev:
    vals = ", ".join(str(v) for v in (e.get("value") or {}).get("values", []))
    out.append(f"| {e['id']} | {e['kind']} | {e['strength']} | `{e['locator']['path']}` | {e['summary'].replace('|', '/')} | {vals} |")
out += ["", f"## 2. Claims ({len(cm['claims'])}) — each tag `{{C###}}` in `research_paper/paper.md` resolves here", "",
        "| ID | Type | Statement | Evidence | Sources | Origin |", "|---|---|---|---|---|---|"]
for c in cm["claims"]:
    out.append(f"| {c['id']} | {c['claim_type']} | {c['statement'].replace('|', '/')} | {', '.join(c['evidence'])} | {', '.join(c.get('sources', []))} | {c.get('origin', '')} |")
out += ["", f"## 3. Limitations ({len(cm['limitations'])})", "", "| ID | Origin | Statement | Bounds claims | Evidence (verbatim author record) |", "|---|---|---|---|---|"]
for l in cm["limitations"]:
    q = "; ".join(f"{E[x]['locator']['path']}: \"{(E[x].get('notes') or E[x]['summary'])[:90]}\"" for x in l["evidence"])
    out.append(f"| {l['id']} | {l['origin']} | {l['statement']} | {', '.join(l['affects_claims'])} | {q.replace('|', '/')} |")
out += ["", "## 4. Negative results and how each is reported", "", "| Evidence | Decision | Where |", "|---|---|---|"]
for d in cm["negative_result_decisions"]:
    out.append(f"| {d['evidence']} — {E[d['evidence']]['summary']} | {d['decision']} | {d['where']} |")
out += ["", "## 5. Conflicting-results register", "",
        "No two live evidence items in this registry record different values for the same quantity. The conflicts that",
        "exist in the project are between *front ends* (a quantity measured under the previous and the current tooth",
        "detector), not between files. They are reported, not reconciled:", "",
        "| Quantity | Previous front end | Current front end | Source | How the paper handles it |", "|---|---|---|---|---|",
        "| DENTEX crop-classifier pipeline minus constant, FDI-set F1 | -2.61 pp (not separable) | +4.27 pp [+1.58, +7.05] | `RESULTS_LOG` 2026-10-11i | reports the current; Section V states the detector override |",
        "| DENTEX lesion agreement, crop classifier minus constant | -4.18 pp | +17.12 pp | same | current, with 'partly by volume' |",
        "| Lever B rule (lesion detector vs constant) | met on 2 of 3 cohorts | not re-run as a rule | `RESULTS_LOG` 2026-09-04h, 2026-10-11g | both stated (VI-D) |",
        "| Tufts end-to-end numbering | 64.8% | 63.5% (-1.30 pp, not separable) | `RESULTS_LOG` 2026-10-11g | current only |",
        "| Gate-pipeline F1 on DENTEX, two machines, same code | 0.294 (Windows) | 0.300 (macOS) | `transfer.md` §3 | Limitations, 'Additional caveats' |",
        "| Stage 4a in-domain score | 0.923 macro-F1 (crop-level split) | 27.5/16.5/11.0% sensitivity (radiograph split, 3 seeds) | `RESULTS_LOG` 2026-10-10, -13b | both, 0.923 named as the split artefact |",
        "", f"## 6. Literature source registry ({len(src)} cited works; live-verified 23 Nov 2026)", "",
        "| ID | Key | Year | Title | DOI | lookup_verified | Retraction |", "|---|---|---|---|---|---|---|"]
for s in src:
    v = s["verification"]
    out.append(f"| {s['id']} | {s['cite_key']} | {s['year']} | {s['title'][:70].replace('|', '/')} | {s.get('doi') or '—'} | {v.get('lookup_verified')} | {v.get('retraction_status', 'checked' if v.get('retraction_checked') else '—')} |")
Path("research_paper/evidence_registry.md").write_text("\n".join(out) + "\n", encoding="utf-8")
print("written", len(out), "lines")
